"use client";
/* Signed private media URLs are dynamic; native img avoids widening image allowlists. */
/* eslint-disable @next/next/no-img-element */
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import { ListeningAudioPlayer } from "@/components/listening/listening-audio-player";
import type { InterfaceLanguage } from "@/lib/i18n/config";
import { getTranslations } from "@/lib/i18n/runtime";
import type { PracticeSession } from "@/lib/practice/types";
import { submitListeningGroup, submitReadingPractice, type ListeningGroupReview } from "../actions";

export function ListeningPracticeClient({ session, locale }: { session: PracticeSession; locale: InterfaceLanguage }) {
  if (session.questions[0]?.part === 3 || session.questions[0]?.part === 4) return <GroupedListeningPractice session={session} locale={locale} />;
  return <SingleListeningPractice session={session} locale={locale} />;
}

function SingleListeningPractice({ session, locale }: { session: PracticeSession; locale: InterfaceLanguage }) {
  const t = getTranslations(locale); const router = useRouter(); const [index, setIndex] = useState(0); const [answers, setAnswers] = useState<Record<string,string>>({}); const [error, setError] = useState(""); const [pending, startTransition] = useTransition(); const question = session.questions[index]; const audio = question.media?.find((m) => m.kind === "AUDIO"); const image = question.media?.find((m) => m.kind === "IMAGE");
  function submit() { startTransition(async () => { const result = await submitReadingPractice(session.id, session.questions.map((q) => ({ questionId: q.id, selectedOptionId: answers[q.id] ?? null }))); if (!result.ok) { setError(t.practice.submitError); return; } router.push(`/practice/${session.id}/results`); }); }
  return <main className="min-h-screen bg-slate-50 px-4 py-5 text-slate-900"><div className="mx-auto max-w-2xl"><header className="flex items-center justify-between"><Link className="font-semibold text-teal-700" href="/practice">{t.practice.exit}</Link><span className="text-sm font-semibold">{t.practice.question} {index + 1} {t.practice.of} {session.questionCount}</span></header><section className="mt-6 rounded-3xl border border-slate-200 bg-white p-5 sm:p-8"><p className="text-sm font-black uppercase tracking-wider text-teal-700">{t.listening.title} · Part {question.part} · {question.part === 1 ? t.listening.photographs : t.listening.questionResponse}</p>{image ? <img alt={image.alt} className="mt-5 max-h-[55vh] w-full rounded-2xl object-contain" onError={() => setError(t.listening.imageUnavailable)} src={image.url} /> : null}<div className="mt-5">{audio ? <ListeningAudioPlayer assetId={audio.id} initialUrl={audio.url} labels={t.listening.audio} questionId={question.id} sessionId={session.id} /> : null}</div><fieldset className="mt-6"><legend className="font-bold">{t.listening.choose}</legend><div className={`mt-3 grid gap-3 ${question.part === 1 ? "grid-cols-2 sm:grid-cols-4" : "grid-cols-3"}`}>{question.options.map((option) => <label className={`flex min-h-14 cursor-pointer items-center justify-center rounded-xl border text-xl font-black ${answers[question.id] === option.id ? "border-teal-600 bg-teal-50 ring-1 ring-teal-600" : "border-slate-300"}`} key={option.id}><input className="sr-only" name={question.id} onChange={() => setAnswers((value) => ({ ...value, [question.id]: option.id }))} type="radio" />{option.key}</label>)}</div></fieldset></section>{error ? <p className="mt-4 rounded-xl bg-red-50 p-4 text-red-700" role="alert">{error}</p> : null}<div className="mt-5 flex gap-3"><button className="min-h-12 rounded-xl border bg-white px-5 font-bold disabled:opacity-40" disabled={index === 0} onClick={() => setIndex(index - 1)} type="button">{t.practice.previous}</button>{index + 1 < session.questionCount ? <button className="ml-auto min-h-12 rounded-xl bg-slate-900 px-5 font-bold text-white" onClick={() => setIndex(index + 1)} type="button">{t.practice.next}</button> : <button className="ml-auto min-h-12 rounded-xl bg-teal-700 px-5 font-bold text-white disabled:opacity-50" disabled={pending} onClick={submit} type="button">{pending ? t.practice.submitting : t.practice.submit}</button>}</div></div></main>;
}

function GroupedListeningPractice({ session, locale }: { session: PracticeSession; locale: InterfaceLanguage }) {
  const t = getTranslations(locale); const router = useRouter(); const [groupIndex, setGroupIndex] = useState(0); const [answers, setAnswers] = useState<Record<string, string>>({}); const [review, setReview] = useState<ListeningGroupReview | null>(null); const [error, setError] = useState(""); const [pending, startTransition] = useTransition(); const group = session.groups[groupIndex]; const first = group.questions[0]; const audio = first.media?.find((m) => m.kind === "AUDIO"); const image = first.media?.find((m) => m.kind === "IMAGE"); const part = first.part as 3 | 4; const labels = t.listening;
  function submitSet() { if (group.questions.some((q) => !answers[q.id])) { setError(labels.answerAll); return; } setError(""); startTransition(async () => { const result = await submitListeningGroup(session.id, group.id, group.questions.map((q) => ({ questionId: q.id, selectedOptionId: answers[q.id] }))); if (!result.ok) { setError(t.practice.submitError); return; } setReview(result.review); }); }
  function next() { if (groupIndex + 1 === session.groups.length) { router.push(`/practice/${session.id}/results`); return; } setGroupIndex((value) => value + 1); setReview(null); setError(""); }
  return <main className="min-h-screen bg-slate-50 px-4 py-5 text-slate-900"><div className="mx-auto max-w-3xl"><header className="flex items-center justify-between gap-4"><Link className="font-semibold text-teal-700" href="/practice">{t.practice.exit}</Link><span className="text-sm font-semibold">{labels.set} {groupIndex + 1} {t.practice.of} {session.groups.length}</span></header><section className="mt-6 overflow-hidden rounded-3xl border border-slate-200 bg-white p-5 sm:p-8"><p className="text-sm font-black uppercase tracking-wider text-teal-700">{labels.title} · Part {part} · {part === 3 ? labels.conversations : labels.talks}</p><p className="mt-2 text-sm text-slate-500">{labels.questions} {group.questions[0].number}–{group.questions.at(-1)!.number}</p>{image ? <img alt={image.alt} className="mt-5 max-h-[55vh] w-full rounded-2xl object-contain" src={image.url} /> : null}{audio ? <div className="mt-5"><ListeningAudioPlayer assetId={audio.id} initialUrl={audio.url} labels={labels.audio} questionId={first.id} sessionId={session.id} /></div> : null}<div className="mt-7 space-y-7">{group.questions.map((question) => <fieldset key={question.id} disabled={Boolean(review)}><legend className="font-bold">{question.number}. {question.text}</legend><div className="mt-3 grid gap-3">{question.options.map((option) => { const result = review?.questions.find((q) => q.questionId === question.id); const highlighted = result && option.id === result.correctOptionId; return <label className={`flex min-h-12 cursor-pointer items-center gap-3 rounded-xl border px-4 py-3 ${highlighted ? "border-emerald-600 bg-emerald-50" : answers[question.id] === option.id ? "border-teal-600 bg-teal-50" : "border-slate-300"}`} key={option.id}><input checked={answers[question.id] === option.id} name={question.id} onChange={() => setAnswers((value) => ({ ...value, [question.id]: option.id }))} type="radio"/><strong>{option.key}.</strong><span className="min-w-0 break-words">{option.text}</span></label>})}</div>{review ? <p className="mt-3 rounded-xl bg-slate-50 p-3 text-sm">{review.questions.find((q) => q.questionId === question.id)?.isCorrect ? "✓" : "✕"} {locale === "vi" ? review.questions.find((q) => q.questionId === question.id)?.explanationVi : review.questions.find((q) => q.questionId === question.id)?.explanationEn}</p> : null}</fieldset>)}</div>{review ? <section className="mt-7 rounded-2xl bg-amber-50 p-5"><h2 className="font-black">{part === 3 ? labels.conversationTranscript : labels.talkTranscript}</h2><p className="mt-3 whitespace-pre-line leading-7">{review.transcript}</p></section> : null}</section>{error ? <p className="mt-4 rounded-xl bg-red-50 p-4 text-red-700" role="alert">{error}</p> : null}<button className="mt-5 min-h-12 w-full rounded-xl bg-teal-700 px-5 font-bold text-white disabled:opacity-50" disabled={pending} onClick={review ? next : submitSet} type="button">{pending ? t.practice.submitting : review ? t.practice.next : labels.submitSet}</button></div></main>;
}
